  1087    assert(coap_pdu_parse_header_size(proto, data) <= length);
  1088
  1089    size_t size = 0;
  1090    const uint8_t *token_start = NULL;
  1091
  1092    if ((proto == COAP_PROTO_TCP || proto == COAP_PROTO_TLS) && length >= 1) {
  1093      uint8_t len = *data >> 4;
  1094      uint8_t tkl = *data & 0x0f;
